const fs=require('fs');const path=require('path');const root=path.resolve(__dirname,'..');
const css=['assets/css/base.css','assets/css/collaboration.css','assets/css/polish.css','assets/css/accessibility.css','assets/css/responsive.css','assets/css/enhancements.css','assets/css/workflow.css','assets/css/service-tools.css','assets/css/business-suite.css','assets/css/productivity.css','assets/css/priority-13-15.css','assets/css/print.css','assets/css/v342-stock-receipt.css','assets/css/v343-mobile-ux.css','assets/css/v344-performance-ux.css','assets/css/v345-board-reports-print.css','assets/css/v346-thermal-calibration.css','assets/css/v347-identity-receipt.css','assets/css/v348-password-reset.css','assets/css/v349-theme-settings-plans.css','assets/css/v350-settings-guide-board.css','assets/css/v351-customer-store.css','assets/css/v352-offline-performance.css','assets/css/v353-attendance-health.css'];
const js=['assets/js/core.js','assets/js/workflow.js','assets/js/operations.js','assets/js/dashboard.js','assets/js/account.js','assets/js/customer-portal.js','assets/js/ui-system.js','assets/js/service-tools.js','assets/js/business-core.js','assets/js/warranty-suite.js','assets/js/inventory-core.js','assets/js/inventory-suite.js','assets/js/analytics.js','assets/js/productivity.js','assets/js/priority-13-15.js','assets/js/boot.js','assets/js/v341-refinements.js','assets/js/v342-stock-receipt.js','assets/js/v343-mobile-ux.js','assets/js/v344-performance-ux.js','assets/js/v345-board-reports-print.js','assets/js/v348-password-reset.js','assets/js/v349-theme-settings-plans.js','assets/js/v350-settings-guide-board.js','assets/js/v351-customer-store.js','assets/js/v352-offline-performance.js','assets/js/v353-attendance-health.js'];
function bundle(files,type){return `/* RepairLog v3.5.3 runtime bundle — generated by scripts/build-bundles.js. */\n`+files.map(file=>`\n/* source: ${file} */\n${fs.readFileSync(path.join(root,file),'utf8')}\n${type==='js'?';':''}\n`).join('')}
fs.writeFileSync(path.join(root,'assets/css/repairlog-v353.bundle.css'),bundle(css,'css'));fs.writeFileSync(path.join(root,'assets/js/repairlog-v353.bundle.js'),bundle(js,'js'));console.log(JSON.stringify({cssSources:css.length,jsSources:js.length,cssBytes:fs.statSync(path.join(root,'assets/css/repairlog-v353.bundle.css')).size,jsBytes:fs.statSync(path.join(root,'assets/js/repairlog-v353.bundle.js')).size},null,2));
